SELECT 'batch_010_aa30d1e1_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0f2e057c-5a1','sm-upload-2a26712c-984','sm-upload-3c2f0270-93c','sm-upload-8b54d965-cef','sm-upload-95c704d9-7a3','sm-upload-9d07ba09-a49','sm-upload-cd65bb92-34f','sm-upload-e94697d9-8e4','sm-upload-f748f953-ced','sm-upload-fa58b133-8bc') AND album_id='al-369dc39c99e3a1a27dc05b84aa30d1e1') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0f2e057c-5a1','sm-upload-2a26712c-984','sm-upload-3c2f0270-93c','sm-upload-8b54d965-cef','sm-upload-95c704d9-7a3','sm-upload-9d07ba09-a49','sm-upload-cd65bb92-34f','sm-upload-e94697d9-8e4','sm-upload-f748f953-ced','sm-upload-fa58b133-8bc') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-369dc39c99e3a1a27dc05b84aa30d1e1' AND name='众虫皆歌') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-369dc39c99e3a1a27dc05b84aa30d1e1') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-369dc39c99e3a1a27dc05b84aa30d1e1') AS calculated_size;
